-- Ensure each new printer/accessory has a single selectable catalog option.
INSERT INTO public.product_variants (product_id,color,color_hex,sku,stock,sort)
SELECT p.id,'Padrão',NULL,'CAT-'||upper(replace(p.slug,'-','_')),0,1
FROM public.products p
WHERE p.slug IN ('impressora-3d-bambu-lab-a1','impressora-3d-bambu-lab-a1-mini','impressora-3d-bambu-lab-p2s-combo','impressora-bambu-lab-a1-mini-combo','impressora-bambu-lab-x2d-combo','impressora-bambu-lab-a2l-combo','impressora-bambu-lab-a2l','impressora-3d-bambu-lab-p1s','impressora-bambu-lab-p1s-combo','impressora-3d-elegoo-centauri-carbon-2-combo','impressora-3d-flashforge-adventure-ad5x-kit-enclausuramento','placa-fria-cool-plate-bambu-lab-a1-p1-x1-multfila','hotend-aco-endurecido-02mm-serie-a1','placa-pei-texturizado-dourado-dupla-face-a1-p1-x1-multfila','placa-fria-pro-cool-plate-bambu-lab-a1-p1-x1-multfila','hotend-aco-inoxidavel-02mm-serie-x1-p1','conjunto-hotend-completo-aco-endurecido-04mm-serie-p1','secador-filamento-3d-drybox-printalot','bico-025mm-impressora-3d-ad5x-flashforge','hotend-aco-endurecido-06mm-serie-x1-p1','placa-fria-cool-plate-bambu-lab-h2d-multfila','modulo-ifs-4-cores-flashforge-ad5x','kit-ferramentas-35-em-1-impressao-3d-multfila','caneta-multpen-impressao-3d','resina-uv-fotopolimerizavel-impressao-3d-200g-multfila','resina-uv-fotopolimerizavel-impressao-3d-100g-multfila','kit-canetas-acrilicas-48-cores-3d-maker-multfila','parafusadeira-eletrica-precisao-multfila-48-bits')
ON CONFLICT (product_id,color) DO NOTHING;
